export default JSON.parse("{\"schema\":\"ai-brain.semantic-merge.v1\",\"id\":\"myths-in-the-way-of-interpersonal-effectiveness-myths-in-the-way-of-objectives-e-e395033b34db\",\"title\":\"Myths in the Way of Interpersonal Effectiveness Myths in the Way of Objectives Effectiveness \\u0003 \u0089 1. I don\u2019t deserve to get what I want or need.\",\"domain\":\"dbt\",\"relatedDomains\":[\"dbt\"],\"purpose\":\"handout\",\"capabilities\":[\"dbt\",\"reference\",\"research\"],\"similarityReview\":{\"threshold\":0.75,\"pairScores\":[0.9764],\"method\":\"5-token shingle Jaccard within same explicit purpose/title context\"},\"provenance\":{\"mergePolicy\":\"shared structure/content consolidated; unique list items/fields retained; scalar conflicts retained as _merged_values\",\"sources\":[{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/03-dbt-interpersonal-effectiveness-interpersonal-effectiveness-handout-2a-myths-in-the-way-o-c50c9b4526.json\",\"sha256\":\"c50c9b452698dd57a85acaaa8c8d3e86114c770f4d2734972cd3ca22627f5772\",\"domain\":\"dbt\",\"bytes\":6333},{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/interpersonal-effectiveness-handout-2a-myths-in-the-way-of-interpersonal-effectiveness-myths-8141dd3baa.json\",\"sha256\":\"8141dd3baa95eafa19c03994709198459080569525de15aa9424b67ac551c898\",\"domain\":\"dbt\",\"bytes\":6165}]},\"data\":{\"pages\":[{\"pdf_page\":143,\"book_page\":\"119\",\"text\":\"119\\nFrom DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Copyright 2015 by Marsha M. Linehan. Permission\\nto photocopy this handout is granted to purchasers of this book for personal use only (see copyright page for details).\\nInterpersonal Effectiveness Handout 2a   (I. E. Worksheet 2)\\nMyths in the Way of Interpersonal Effectiveness\\nMyths in the Way of Objectives Effectiveness\\n\\u0003\\n\u0089   1.\\t I don\u2019t deserve to get what I want or need.\\n\\u0003\\n\u0089   2.\\tIf I make a request, this will show that I am a very weak person.\\n\\u0003\\n\u0089   3.\\tI have to know whether a person is going to say yes before I make a request.\\n\\u0003\\n\u0089   4.\\tIf I ask for something or say no, I can\u2019t stand it if someone gets upset with me.\\n\\u0003\\n\u0089   5.\\tIf they say no, it will kill me.\\n\\u0003\\n\u0089   6.\\tMaking requests is a really pushy (bad, self-centered, selfish, etc.) thing to do.\\n\\u0003\\n\u0089   7.\\t Saying no to a request is always a selfish thing to do.\\n\\u0003\\n\u0089   8.\\tI should be willing to sacrifice my own needs for others.\\n\\u0003\\n\u0089   9.\\tI must be really inadequate if I can\u2019t fix this myself.\\n\\u0003\\n\u0089 10.\\t Obviously, the problem is just in my head. If I would just think differently I wouldn\u2019t have to\\nbother everybody else.\\n\\u0003\\n\u0089 11.\\t If I don\u2019t have what I want or need, it doesn\u2019t make any difference; I don\u2019t care really.\\n\\u0003\\n\u0089 12.\\tSkillfulness is a sign of weakness.\\nOther myth:\\nOther myth:\\nMyths in the Way of Relationship and Self-Respect Effectiveness\\n\\u0003\\n\u0089 13.\\tI shouldn\u2019t have to ask (say no); they should know what I want (and do it).\\n\\u0003\\n\u0089 14.\\t They should have known that their behavior would hurt my feelings; I shouldn\u2019t have to tell\\nthem.\\n\\u0003\\n\u0089 15.\\t I shouldn\u2019t have to negotiate or work at getting what I want.\\n\\u0003\\n\u0089 16.\\tOther people should be willing to do more for my needs.\\n\\u0003\\n\u0089 17.\\t Other people should like, approve of, and support me.\\n\\u0003\\n\u0089 18.\\tThey don\u2019t deserve my being skillful or treating them well.\\n\\u0003\\n\u0089 19.\\t Getting what I want when I want it is most important.\\n\\u0003\\n\u0089 20.\\tI shouldn\u2019t be fair, kind, courteous, or respectful if others are not so toward me.\\n\\u0003\\n\u0089 21.\\t Revenge will feel so good; it will be worth any negative consequences.\\n\\u0003\\n\u0089 22.\\tOnly wimps have values.\\n\\u0003\\n\u0089 23.\\tEverybody lies.\\n\\u0003\\n\u0089 24.\\tGetting what I want is more important than how I get it; the ends really do justify the means.\\nOther myth:\\nOther myth:\"}],\"copyright_notice\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\",\"source_marker\":\"Interpersonal Effectiveness Handout 2a   (I. E. Worksheet 2)\",\"source_pdf_pages\":[143],\"fillable_html_created\":false,\"created_at\":\"2026-06-25T17:33:54\",\"json_path\":\"json/items/interpersonal_effectiveness/handouts/interpersonal_effectiveness_handout_2a_myths_in_the_way_of_interpersonal_effectiveness_myths_in_the_way_of_ob.json\",\"item_number\":\"2a\",\"full_text\":\"Interpersonal Effectiveness Handout 2a   (I. E. Worksheet 2)\\nMyths in the Way of Interpersonal Effectiveness\\nMyths in the Way of Objectives Effectiveness\\n\\u0003\\n\u0089   1.\\t I don\u2019t deserve to get what I want or need.\\n\\u0003\\n\u0089   2.\\tIf I make a request, this will show that I am a very weak person.\\n\\u0003\\n\u0089   3.\\tI have to know whether a person is going to say yes before I make a request.\\n\\u0003\\n\u0089   4.\\tIf I ask for something or say no, I can\u2019t stand it if someone gets upset with me.\\n\\u0003\\n\u0089   5.\\tIf they say no, it will kill me.\\n\\u0003\\n\u0089   6.\\tMaking requests is a really pushy (bad, self-centered, selfish, etc.) thing to do.\\n\\u0003\\n\u0089   7.\\t Saying no to a request is always a selfish thing to do.\\n\\u0003\\n\u0089   8.\\tI should be willing to sacrifice my own needs for others.\\n\\u0003\\n\u0089   9.\\tI must be really inadequate if I can\u2019t fix this myself.\\n\\u0003\\n\u0089 10.\\t Obviously, the problem is just in my head. If I would just think differently I wouldn\u2019t have to\\nbother everybody else.\\n\\u0003\\n\u0089 11.\\t If I don\u2019t have what I want or need, it doesn\u2019t make any difference; I don\u2019t care really.\\n\\u0003\\n\u0089 12.\\tSkillfulness is a sign of weakness.\\nOther myth:\\nOther myth:\\nMyths in the Way of Relationship and Self-Respect Effectiveness\\n\\u0003\\n\u0089 13.\\tI shouldn\u2019t have to ask (say no); they should know what I want (and do it).\\n\\u0003\\n\u0089 14.\\t They should have known that their behavior would hurt my feelings; I shouldn\u2019t have to tell\\nthem.\\n\\u0003\\n\u0089 15.\\t I shouldn\u2019t have to negotiate or work at getting what I want.\\n\\u0003\\n\u0089 16.\\tOther people should be willing to do more for my needs.\\n\\u0003\\n\u0089 17.\\t Other people should like, approve of, and support me.\\n\\u0003\\n\u0089 18.\\tThey don\u2019t deserve my being skillful or treating them well.\\n\\u0003\\n\u0089 19.\\t Getting what I want when I want it is most important.\\n\\u0003\\n\u0089 20.\\tI shouldn\u2019t be fair, kind, courteous, or respectful if others are not so toward me.\\n\\u0003\\n\u0089 21.\\t Revenge will feel so good; it will be worth any negative consequences.\\n\\u0003\\n\u0089 22.\\tOnly wimps have values.\\n\\u0003\\n\u0089 23.\\tEverybody lies.\\n\\u0003\\n\u0089 24.\\tGetting what I want is more important than how I get it; the ends really do justify the means.\\nOther myth:\\nOther myth:\",\"source_pdf\":\"DBT Skills Workbook.pdf\",\"related_references\":[\"I. E. Worksheet 2\"],\"id\":\"interpersonal_effectiveness_handout_2a\",\"item_type\":\"handout\",\"is_example\":false,\"source_book_pages\":[\"119\"],\"title\":\"Myths in the Way of Interpersonal Effectiveness Myths in the Way of Objectives Effectiveness \\u0003 \u0089 1. I don\u2019t deserve to get what I want or need.\",\"module_category\":\"Interpersonal Effectiveness Skills\",\"shared_json_path\":\"shared/03_dbt_interpersonal_effectiveness/handouts_json/interpersonal_effectiveness_handout_2a_myths_in_the_way_of_interpersonal_4edbde1a.json\",\"module\":\"Interpersonal Effectiveness\",\"keywords\":[\"Effectiveness\",\"Interpersonal\",\"Myths\",\"Objectives\",\"deserve\",\"need\",\"want\",\"what\"]}}");
